//! `ColorSpace::ColorConverter`.

use super::rgb::Rgb;

pub struct ColorConverter;

impl ColorConverter {
    /// Linear per-channel blend of `a` towards `b`.
    ///
    /// Evaluated as `a * (1 - ratio) + b * ratio` in `f32`, matching the C++
    /// library bit for bit. The associativity matters: the algebraically
    /// equivalent `a + (b - a) * ratio` disagrees in the last bits and those
    /// bits become visible whenever the two terms cancel (e.g. `a = 1`,
    /// `b = -9`, `ratio = 0.1` prints `-5.96046e-08`, not `0`).
    ///
    /// `ratio` is neither clamped nor validated, so values outside `[0, 1]`
    /// extrapolate.
    pub fn blend(a: Rgb, b: Rgb, ratio: f32) -> Rgb {
        let inv = 1.0f32 - ratio;
        Rgb::new(
            a.r * inv + b.r * ratio,
            a.g * inv + b.g * ratio,
            a.b * inv + b.b * ratio,
        )
    }
}

