//! Reproduces `std::cout << some_float` for a default-configured stream.
//!
//! `operator<<(float)` promotes to `double` (exactly) and prints it in
//! `defaultfloat` with the stream's default precision of 6 — i.e. exactly
//! `printf("%g", value)`.

/// Formats `v` the way `std::cout << v` would for a `float`.
pub fn ostream_float(v: f32) -> String {
    format_g(v as f64, 6)
}

/// `printf("%.*g", precision, v)`, without the `#` flag.
fn format_g(v: f64, precision: usize) -> String {
    // glibc prints the sign of a NaN; Rust's own formatter prints "NaN".
    if v.is_nan() {
        return if v.is_sign_negative() { "-nan" } else { "nan" }.to_string();
    }
    if v.is_infinite() {
        return if v.is_sign_negative() { "-inf" } else { "inf" }.to_string();
    }

    // %g with precision 0 behaves as precision 1.
    let p = precision.max(1);

    // The style choice is made on the decimal exponent X *after* rounding to p
    // significant digits, which is what %e yields: 999999.5 rounds to
    // 1.00000e+06, so X == 6 and the %e style wins ("1e+06", not "999999" or
    // "1000000"). Rust's precision-qualified float formatting is exact and
    // correctly rounded, so it can stand in for the C library here.
    let sci = format!("{:.*e}", p - 1, v);
    let e_at = sci.find('e').expect("{:e} always emits an exponent");
    let exp: i32 = sci[e_at + 1..].parse().expect("exponent is an integer");

    if exp < -4 || exp >= p as i32 {
        // %e style: mantissa with p-1 fraction digits, exponent at least 2
        // digits and always signed.
        let mantissa = strip_trailing_zeros(&sci[..e_at]);
        let sign = if exp < 0 { '-' } else { '+' };
        format!("{}e{}{:02}", mantissa, sign, exp.unsigned_abs())
    } else {
        // %f style with p-1-X fraction digits. Note this rounds the original
        // value again rather than reusing the %e digits, exactly as printf does.
        let frac_digits = (p as i32 - 1 - exp) as usize;
        strip_trailing_zeros(&format!("{:.*}", frac_digits, v))
    }
}

/// Drops trailing fractional zeros, and a bare trailing point, as `%g` does
/// when the `#` flag is absent. Leaves integral strings untouched.
fn strip_trailing_zeros(s: &str) -> String {
    if !s.contains('.') {
        return s.to_string();
    }
    s.trim_end_matches('0').trim_end_matches('.').to_string()
}

#[cfg(test)]
mod tests {
    use super::ostream_float;

    #[test]
    fn matches_cout_defaults() {
        // Values cross-checked against the C++ binary.
        assert_eq!(ostream_float(0.34), "0.34");
        assert_eq!(ostream_float(2.0), "2");
        assert_eq!(ostream_float(100.0), "100");
        assert_eq!(ostream_float(0.0), "0");
        assert_eq!(ostream_float(-0.0), "-0");
        assert_eq!(ostream_float(1e8), "1e+08");
        assert_eq!(ostream_float(123456789.0), "1.23457e+08");
        assert_eq!(ostream_float(1234567.0), "1.23457e+06");
        assert_eq!(ostream_float(123456.7), "123457");
        assert_eq!(ostream_float(1.234567), "1.23457");
        assert_eq!(ostream_float(0.0001), "0.0001");
        assert_eq!(ostream_float(0.00001), "1e-05");
        assert_eq!(ostream_float(999999.5), "1e+06");
        assert_eq!(ostream_float(-5.96046448e-8), "-5.96046e-08");
        assert_eq!(ostream_float(3.4e38), "3.4e+38");
        assert_eq!(ostream_float(f32::INFINITY), "inf");
        assert_eq!(ostream_float(f32::NEG_INFINITY), "-inf");
        assert_eq!(ostream_float(f32::NAN), "nan");
        assert_eq!(ostream_float(-f32::NAN), "-nan");
    }
}

