//! Reproduces `std::stof`, i.e. `strtof` plus the two exceptions the C++
//! wrapper adds.
//!
//! The grammar is the C one, so it is considerably more permissive than Rust's
//! `str::parse::<f32>()`: leading whitespace is skipped, a trailing unparsed
//! tail is ignored (`"0.5xyz"` is `0.5`), and hex literals (`"0x10"` is `16`)
//! and `"nan(chars)"` are accepted. It is also stricter about range: anything
//! that overflows to infinity *or* underflows to a subnormal sets `ERANGE`,
//! which `std::stof` turns into `std::out_of_range` — so `"1e-38"` throws even
//! though `"1.18e-38"` does not.

/// Smallest positive *normal* `f32`; anything below is a subnormal, i.e. an
/// underflow as far as `strtof` is concerned.
const MIN_NORMAL: f32 = f32::MIN_POSITIVE;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StofError {
    /// `std::invalid_argument`: no conversion could be performed.
    Invalid,
    /// `std::out_of_range`: the value over- or underflowed `float`.
    OutOfRange,
}

impl StofError {
    /// The C++ exception type name, as `std::terminate` reports it.
    pub fn exception_name(self) -> &'static str {
        match self {
            StofError::Invalid => "std::invalid_argument",
            StofError::OutOfRange => "std::out_of_range",
        }
    }
}

/// What the scanned subject sequence denoted, which decides whether a
/// non-finite result is legitimate or an overflow.
enum Subject {
    /// A finite decimal/hex numeral, with whether any significant digit was
    /// nonzero (a `0` result from nonzero digits is an underflow).
    Numeral { value: f32, nonzero_digits: bool },
    /// A literal `inf`/`infinity`/`nan`, which never sets `ERANGE`.
    Literal(f32),
}

pub fn stof(s: &str) -> Result<f32, StofError> {
    let b = s.as_bytes();
    let mut i = 0;

    while i < b.len() && is_c_space(b[i]) {
        i += 1;
    }

    let negative = match b.get(i) {
        Some(b'+') => {
            i += 1;
            false
        }
        Some(b'-') => {
            i += 1;
            true
        }
        _ => false,
    };

    let rest = &b[i..];
    let subject = scan_infinity(rest)
        .or_else(|| scan_nan(rest))
        .or_else(|| scan_hex(rest))
        .or_else(|| scan_decimal(rest))
        .ok_or(StofError::Invalid)?;

    match subject {
        Subject::Literal(v) => Ok(with_sign(v, negative)),
        Subject::Numeral {
            value,
            nonzero_digits,
        } => {
            // ERANGE cases. A zero or subnormal result is only an underflow if
            // the digits actually denoted something nonzero: plain "0" is fine.
            if value.is_infinite() {
                return Err(StofError::OutOfRange);
            }
            if nonzero_digits && value.abs() < MIN_NORMAL {
                return Err(StofError::OutOfRange);
            }
            Ok(with_sign(value, negative))
        }
    }
}

fn with_sign(v: f32, negative: bool) -> f32 {
    if negative {
        -v
    } else {
        v
    }
}

/// The C locale's whitespace set, which is what `strtof` skips.
fn is_c_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

fn matches_ci(b: &[u8], word: &[u8]) -> bool {
    b.len() >= word.len()
        && b[..word.len()]
            .iter()
            .zip(word)
            .all(|(a, w)| a.to_ascii_lowercase() == *w)
}

/// `inf` or the longer `infinity`.
fn scan_infinity(b: &[u8]) -> Option<Subject> {
    if matches_ci(b, b"inf") {
        Some(Subject::Literal(f32::INFINITY))
    } else {
        None
    }
}

/// `nan`, optionally followed by a parenthesised charseq which we ignore.
fn scan_nan(b: &[u8]) -> Option<Subject> {
    if matches_ci(b, b"nan") {
        Some(Subject::Literal(f32::NAN))
    } else {
        None
    }
}

/// `0x` hex significand with an optional binary `p` exponent.
fn scan_hex(b: &[u8]) -> Option<Subject> {
    if !(b.len() >= 2 && b[0] == b'0' && (b[1] | 0x20) == b'x') {
        return None;
    }

    let mut i = 2;
    // Significand digits are accumulated as one integer plus a power-of-two
    // scale, so `.` only shifts the scale.
    let mut sig: u128 = 0;
    let mut sticky = false;
    let mut scale: i32 = 0;
    let mut digits = 0usize;
    let mut nonzero = false;
    let mut seen_point = false;

    while i < b.len() {
        let c = b[i];
        if c == b'.' && !seen_point {
            seen_point = true;
            i += 1;
            continue;
        }
        let Some(d) = (c as char).to_digit(16) else {
            break;
        };
        digits += 1;
        nonzero |= d != 0;
        if sig <= (u128::MAX >> 4) {
            sig = sig * 16 + d as u128;
        } else {
            // Out of room: the digit only survives as a sticky bit.
            sticky |= d != 0;
            scale += 4;
        }
        if seen_point {
            scale -= 4;
        }
        i += 1;
    }

    if digits == 0 {
        // "0x" with no digits after it: the subject sequence is just the "0".
        return Some(Subject::Numeral {
            value: 0.0,
            nonzero_digits: false,
        });
    }

    if i < b.len() && (b[i] | 0x20) == b'p' {
        if let Some((exp, len)) = scan_exponent_digits(&b[i + 1..]) {
            scale = scale.saturating_add(exp);
            i += 1 + len;
        }
    }
    let _ = i;

    Some(Subject::Numeral {
        value: scaled_to_f32(sig, sticky, scale),
