//! Port of `dataset/color/tests/test7.cpp`.
//!
//! Blends two RGB colors and prints the result. Mirrors the C++ entry point
//! including its argument handling quirks: five values are read from argv but
//! `b2` never is (it keeps its default), and the sixth argument is the blend
//! ratio, so a seventh argument is ignored.

#[path = "src/color/mod.rs"]
mod color;

use color::cxx_fmt::ostream_float;
use color::cxx_parse::{stof, StofError};
use color::{ColorConverter, Rgb};

/// Stands in for an uncaught C++ exception: `std::terminate` reports the type
/// and `what()` on stderr, then `abort()` raises SIGABRT (status 134).
fn terminate(err: StofError) -> ! {
    eprintln!(
        "terminate called after throwing an instance of '{}'",
        err.exception_name()
    );
    eprintln!("  what():  stof");
    std::process::abort();
}

fn parse_arg(arg: &str) -> f32 {
    match stof(arg) {
        Ok(v) => v,
        Err(e) => terminate(e),
    }
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let argc = argv.len();

    let (mut r1, mut g1, mut b1) = (0.3f32, 0.4f32, 0.5f32);
    let (mut r2, mut g2) = (0.7f32, 0.2f32);
    // Never overridden from argv, matching the C++ source.
    let b2 = 0.1f32;
    let mut ratio = 0.3f32;

    if argc > 5 {
        r1 = parse_arg(&argv[1]);
        g1 = parse_arg(&argv[2]);
        b1 = parse_arg(&argv[3]);
        r2 = parse_arg(&argv[4]);
        g2 = parse_arg(&argv[5]);
    }
    if argc > 6 {
        ratio = parse_arg(&argv[6]);
    }

    let rgb1 = Rgb::new(r1, g1, b1);
    let rgb2 = Rgb::new(r2, g2, b2);
    let result = ColorConverter::blend(rgb1, rgb2, ratio);
    println!(
        "{} {} {}",
        ostream_float(result.r),
        ostream_float(result.g),
        ostream_float(result.b)
    );
}

