/// `sig * 2^exp`, correctly rounded to `f32`, with `sticky` marking discarded
/// nonzero low-order bits.
fn scaled_to_f32(mut sig: u128, sticky: bool, mut exp: i32) -> f32 {
    if sig == 0 {
        return 0.0;
    }
    if sticky && sig & 1 == 0 {
        sig |= 1;
    }
    // Trim to 53 bits so the `as f64` below is exact, keeping a sticky bit so
    // ties still break the right way.
    let bits = 128 - sig.leading_zeros();
    if bits > 53 {
        let shift = bits - 53;
        let lost = sig & ((1u128 << shift) - 1);
        sig >>= shift;
        exp = exp.saturating_add(shift as i32);
        if lost != 0 && sig & 1 == 0 {
            sig |= 1;
        }
    }
    // f64 has far more range than f32, so an f32-representable result can never
    // over- or underflow here.
    ((sig as f64) * (2f64).powi(exp.clamp(-4000, 4000))) as f32
}

