/// The `FLT_MIN` / `FLT_MAX` boundaries, all confirmed against the C++
/// binary. `2^-126` is 1.17549435082228750796873653722224567781866...e-38
/// and `FLT_MAX` is 3.40282346638528859811704183484516925440e38.
#[test]
fn boundary_cases_match_strtof() {
    // Tininess is judged after rounding to 24 bits with an unbounded
    // exponent, so these two straddle the boundary despite both being
    // below 2^-126 and both returning FLT_MIN.
    assert_eq!(stof("1.1754943e-38"), Err(StofError::OutOfRange));
    assert_eq!(stof("1.17549435e-38"), Ok(f32::MIN_POSITIVE));
    assert_eq!(stof("1.175494350822287507e-38"), Ok(f32::MIN_POSITIVE));
    assert_eq!(
        stof("1.17549435082228750796873653722224567781866555677208752150875e-38"),
        Ok(f32::MIN_POSITIVE)
    );
    assert_eq!(stof("1.1754944e-38"), Ok(f32::MIN_POSITIVE));

    // Overflow, by contrast, is judged on the rounded result: values past
    // FLT_MAX are fine until they round to infinity. The exact tie
    // 2^128 - 2^103 rounds to even, i.e. to infinity.
    assert_eq!(stof("3.4028235e38"), Ok(f32::MAX));
    assert_eq!(stof("3.40282356e38"), Ok(f32::MAX));
    assert_eq!(stof("3.4028235677973366e38"), Ok(f32::MAX));
    assert_eq!(
        stof("3.40282356779733661637539395458142568448e38"),
        Err(StofError::OutOfRange)
    );
    assert_eq!(stof("3.4028236e38"), Err(StofError::OutOfRange));
}

