        for base in ["340282346638528859811704183484516925440", "340282356779733661637539395458142568448"] {
            let mut d: String = base.chars().take(digits).collect();
            let last: i64 = d.pop().unwrap() as i64 - '0' as i64;
            let adj = last + (step - 20);
            if (0..=9).contains(&adj) {
                cases.push(vec![
                    format!("{}{}e{}", d, adj, 39 - digits),
                    s("0"),
                    s("0"),
                    s("0"),
                    s("0"),
                    s("0.0"),
                ]);
            }
        }
    }
}

// 7. Subnormal range and assorted tiny values.
for k in 1..=60i32 {
    for m in ["1", "1.5", "9.99", "5", "2.5", "7.0000001"] {
        cases.push(vec![
            format!("{}e-{}", m, k),
            format!("{}e-{}", m, k + 1),
            s("0"),
            s("0"),
            s("0"),
            s("0.5"),
        ]);
    }
}

